#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <chrono>
#include <random>
using namespace std;

struct State { int countWays, totalSum; State() : countWays(0), totalSum(0) {} State(int c, int s) : countWays(c), totalSum(s) {} };

int totalParts, totalMembers, modVal;
vector<vector<int>> binom;

int sumInterval(int a, int b) { return (a + b) * (b - a + 1) / 2; }

vector<bool> visited2;
vector<State> memo2;

State compute2(int n) {
    if (n == 1) return State(2, 0);
    if (visited2[n]) return memo2[n];
    State res(0, 0);
    for (int i = 0; i < n; ++i) {
        int leftCount = i, rightCount = n - i - 1;
        State leftRes = (leftCount == 0) ? State(1, 0) : compute2(leftCount);
        State rightRes = (rightCount == 0) ? State(1, 0) : compute2(rightCount);
        int ways = (leftCount + 1) + (rightCount + 1);
        int sumAdd = sumInterval(0, leftCount) + sumInterval(0, rightCount);
        int mlt = binom[leftCount + rightCount][leftCount];
        res.countWays = (res.countWays + (long long)leftRes.countWays * ways % modVal * rightRes.countWays) % modVal;
        res.totalSum = (res.totalSum + (long long)leftRes.totalSum * ways % modVal * rightRes.countWays
                        + (long long)leftRes.countWays * sumAdd % modVal * rightRes.countWays
                        + (long long)leftRes.countWays * ways % modVal * rightRes.totalSum) % modVal;
    }
    visited2[n] = true;
    memo2[n] = res;
    return res;
}

vector<vector<bool>> visited1;
vector<vector<State>> memo1;

State compute1(int idx, int cnt) {
    if (totalParts - idx == cnt) return compute2(cnt);
    if (visited1[idx][cnt]) return memo1[idx][cnt];
    State res(0, 0);
    for (int i = idx; i < totalParts; ++i) {
        int leftCount = i - idx;
        int rightCount = cnt - leftCount;
        if (rightCount < 0 || rightCount > totalParts - i - 1) continue;
        State leftRes = (i == idx) ? State(1, 0) : compute2(leftCount);
        State rightRes = (i + 1 == totalParts) ? State(1, 0) : compute1(i + 1, rightCount);
        int mlt = binom[leftCount + rightCount][leftCount];
        res.countWays = (res.countWays + (long long)leftRes.countWays * rightRes.countWays % modVal * mlt) % modVal;
        res.totalSum = (res.totalSum + (long long)leftRes.totalSum * rightRes.countWays % modVal * mlt
                        + (long long)leftRes.countWays * rightRes.totalSum % modVal * mlt) % modVal;
    }
    visited1[idx][cnt] = true;
    memo1[idx][cnt] = res;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ncomp, npers, MOD;
    cin >> ncomp >> npers >> MOD;
    totalParts = ncomp;
    totalMembers = npers;
    modVal = MOD;
    binom.assign(ncomp + 1, vector<int>(ncomp + 1, 0));
    for (int i = 0; i <= ncomp; ++i) {
        binom[i][0] = 1;
        binom[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD;
        }
    }
    visited2.assign(ncomp + 1, false);
    memo2.assign(ncomp + 1, State());
    visited1.assign(ncomp + 1, vector<bool>(npers + 1, false));
    memo1.assign(ncomp + 1, vector<State>(npers + 1));
    cout << compute1(0, npers).totalSum << "\n";
    return 0;
}
